CREATE OR REPLACE FUNCTION platform_private.catalog_micro_normalize(p jsonb, p_create boolean)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE
 SET search_path TO ''
AS $function$
DECLARE k text; v_out jsonb:='{}'::jsonb; v_num numeric;
  v_text constant jsonb:='{"nome_cientifico":300,"concentracao_label":120,"fornecedor":200,"meio_cultivo":5000,"funcao_agronomica":5000,"observacoes":5000,"descricao":5000}';
BEGIN
  IF p IS NULL OR pg_catalog.jsonb_typeof(p) IS DISTINCT FROM 'object' THEN RAISE EXCEPTION USING ERRCODE='22023', MESSAGE='catalog_entity_invalid'; END IF;
  FOR k IN SELECT pg_catalog.jsonb_object_keys(p) LOOP
    IF k = 'nome' THEN
      IF pg_catalog.jsonb_typeof(p->k) IS DISTINCT FROM 'string' OR pg_catalog.char_length(pg_catalog.btrim(p->>k)) NOT BETWEEN 1 AND 200 THEN
        RAISE EXCEPTION USING ERRCODE='22023', MESSAGE='catalog_entity_invalid'; END IF;
      v_out:=v_out||pg_catalog.jsonb_build_object(k,pg_catalog.btrim(p->>k));
    ELSIF k = 'tipo' THEN
      -- tipo define prefixo do código gerado no servidor: somente na criação.
      IF NOT p_create OR pg_catalog.jsonb_typeof(p->k) IS DISTINCT FROM 'string'
        OR NOT ((p->>k) = ANY(pg_catalog.enum_range(NULL::public.tipo_microrganismo)::text[])) THEN
        RAISE EXCEPTION USING ERRCODE='22023', MESSAGE='catalog_entity_invalid'; END IF;
      v_out:=v_out||pg_catalog.jsonb_build_object(k,p->>k);
    ELSIF k = 'producao_on_farm' THEN
      IF pg_catalog.jsonb_typeof(p->k) IS DISTINCT FROM 'boolean' THEN RAISE EXCEPTION USING ERRCODE='22023', MESSAGE='catalog_entity_invalid'; END IF;
      v_out:=v_out||pg_catalog.jsonb_build_object(k,p->k);
    ELSIF k = 'concentracao_ufc_ml' THEN
      IF pg_catalog.jsonb_typeof(p->k)='null' THEN v_out:=v_out||pg_catalog.jsonb_build_object(k,NULL::numeric);
      ELSE
        IF pg_catalog.jsonb_typeof(p->k) IS DISTINCT FROM 'number' THEN RAISE EXCEPTION USING ERRCODE='22023', MESSAGE='catalog_entity_invalid'; END IF;
        v_num:=(p->>k)::numeric;
        -- Limite alinhado ao front: <= 9007199254740991 (Number.MAX_SAFE_INTEGER) e até 2 casas, sem notação exponencial.
        IF v_num <= 0 OR v_num > 9007199254740991 OR pg_catalog.scale(v_num) > 2 OR (p->>k) ~* 'e' THEN RAISE EXCEPTION USING ERRCODE='22023', MESSAGE='catalog_entity_invalid'; END IF;
        v_out:=v_out||pg_catalog.jsonb_build_object(k,v_num);
      END IF;
    ELSIF v_text ? k THEN
      IF pg_catalog.jsonb_typeof(p->k)='null' THEN v_out:=v_out||pg_catalog.jsonb_build_object(k,NULL::text);
      ELSIF pg_catalog.jsonb_typeof(p->k) IS DISTINCT FROM 'string' OR pg_catalog.char_length(p->>k) > (v_text->>k)::int THEN
        RAISE EXCEPTION USING ERRCODE='22023', MESSAGE='catalog_entity_invalid';
      ELSE v_out:=v_out||pg_catalog.jsonb_build_object(k,NULLIF(pg_catalog.btrim(p->>k),''));
      END IF;
    ELSE RAISE EXCEPTION USING ERRCODE='22023', MESSAGE='catalog_entity_invalid';
    END IF;
  END LOOP;
  IF p_create AND NOT (v_out ? 'nome' AND v_out ? 'tipo' AND v_out ? 'producao_on_farm') THEN
    RAISE EXCEPTION USING ERRCODE='22023', MESSAGE='catalog_entity_invalid'; END IF;
  IF NOT p_create AND v_out = '{}'::jsonb THEN RAISE EXCEPTION USING ERRCODE='22023', MESSAGE='catalog_entity_invalid'; END IF;
  RETURN v_out;
END;
$function$

CREATE OR REPLACE FUNCTION platform_private.catalog_culture_normalize(p jsonb, p_create boolean)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE
 SET search_path TO ''
AS $function$
DECLARE k text; v_out jsonb:='{}'::jsonb;
BEGIN
  IF p IS NULL OR pg_catalog.jsonb_typeof(p) IS DISTINCT FROM 'object' THEN RAISE EXCEPTION USING ERRCODE='22023', MESSAGE='catalog_entity_invalid'; END IF;
  FOR k IN SELECT pg_catalog.jsonb_object_keys(p) LOOP
    IF k = 'nome' AND pg_catalog.jsonb_typeof(p->k)='string' AND pg_catalog.char_length(pg_catalog.btrim(p->>k)) BETWEEN 1 AND 120 THEN
      v_out:=v_out||pg_catalog.jsonb_build_object(k,pg_catalog.btrim(p->>k));
    ELSIF k = 'descricao' AND pg_catalog.jsonb_typeof(p->k)='null' THEN v_out:=v_out||pg_catalog.jsonb_build_object(k,NULL::text);
    ELSIF k = 'descricao' AND pg_catalog.jsonb_typeof(p->k)='string' AND pg_catalog.char_length(p->>k) <= 2000 THEN
      v_out:=v_out||pg_catalog.jsonb_build_object(k,NULLIF(pg_catalog.btrim(p->>k),''));
    ELSE RAISE EXCEPTION USING ERRCODE='22023', MESSAGE='catalog_entity_invalid';
    END IF;
  END LOOP;
  IF (p_create AND NOT v_out ? 'nome') OR (NOT p_create AND v_out='{}'::jsonb) THEN
    RAISE EXCEPTION USING ERRCODE='22023', MESSAGE='catalog_entity_invalid'; END IF;
  RETURN v_out;
END;
$function$

CREATE OR REPLACE FUNCTION platform_private.catalog_entity_replay(p_actor uuid, p_operation text, p_request jsonb, p_reason text, p_key uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE v_existing public.catalog_platform_admin_audit%ROWTYPE;
BEGIN
  IF p_key IS NULL OR p_reason IS NULL OR pg_catalog.char_length(pg_catalog.btrim(p_reason)) NOT BETWEEN 10 AND 500 THEN
    RAISE EXCEPTION USING ERRCODE='22023', MESSAGE='catalog_entity_invalid'; END IF;
  PERFORM pg_catalog.pg_advisory_xact_lock(pg_catalog.hashtextextended('catalog-metadata:'||p_key::text,0));
  SELECT * INTO v_existing FROM public.catalog_platform_admin_audit WHERE correlation_id=p_key;
  IF NOT FOUND THEN RETURN NULL; END IF;
  IF v_existing.actor_id IS DISTINCT FROM p_actor OR v_existing.operation IS DISTINCT FROM p_operation
    OR v_existing.counts_after->'request' IS DISTINCT FROM p_request THEN
    RAISE EXCEPTION USING ERRCODE='40001', MESSAGE='catalog_entity_conflict'; END IF;
  RETURN (v_existing.counts_after->'receipt')||pg_catalog.jsonb_build_object('idempotent',true);
END;
$function$

CREATE OR REPLACE FUNCTION platform_private.catalog_volume_normalize(p jsonb, p_create boolean)
 RETURNS jsonb
 LANGUAGE plpgsql
 IMMUTABLE
 SET search_path TO ''
AS $function$
DECLARE k text; v_out jsonb:='{}'::jsonb; v_num numeric; v_int numeric;
BEGIN
  IF p IS NULL OR pg_catalog.jsonb_typeof(p) IS DISTINCT FROM 'object' THEN RAISE EXCEPTION USING ERRCODE='22023', MESSAGE='catalog_volume_invalid'; END IF;
  FOR k IN SELECT pg_catalog.jsonb_object_keys(p) LOOP
    IF k = 'volume_ml' THEN
      IF pg_catalog.jsonb_typeof(p->k) IS DISTINCT FROM 'string' OR (p->>k) !~ '^[0-9]{1,7}(\.[0-9]{1,3})?$' THEN
        RAISE EXCEPTION USING ERRCODE='22023', MESSAGE='catalog_volume_invalid'; END IF;
      v_num:=(p->>k)::numeric;
      IF v_num <= 0 OR v_num > 1000000 THEN RAISE EXCEPTION USING ERRCODE='22023', MESSAGE='catalog_volume_invalid'; END IF;
      v_out:=v_out||pg_catalog.jsonb_build_object(k,v_num);
    ELSIF k = 'preco_brl' THEN
      IF pg_catalog.jsonb_typeof(p->k) IS DISTINCT FROM 'string' OR (p->>k) !~ '^[0-9]{1,9}(\.[0-9]{1,2})?$' THEN
        RAISE EXCEPTION USING ERRCODE='22023', MESSAGE='catalog_volume_invalid'; END IF;
      v_num:=(p->>k)::numeric;
      -- > 0: preço zero ativo faria o sync anular o pai; preço desconhecido não é cadastrado.
      IF v_num <= 0 THEN RAISE EXCEPTION USING ERRCODE='22023', MESSAGE='catalog_volume_invalid'; END IF;
      v_out:=v_out||pg_catalog.jsonb_build_object(k,v_num);
    ELSIF k = 'rotulo' THEN
      IF pg_catalog.jsonb_typeof(p->k)='null' THEN v_out:=v_out||pg_catalog.jsonb_build_object(k,NULL::text);
      ELSIF pg_catalog.jsonb_typeof(p->k) IS DISTINCT FROM 'string' OR pg_catalog.char_length(pg_catalog.btrim(p->>k)) > 60 THEN
        RAISE EXCEPTION USING ERRCODE='22023', MESSAGE='catalog_volume_invalid';
      ELSE v_out:=v_out||pg_catalog.jsonb_build_object(k,NULLIF(pg_catalog.btrim(p->>k),''));
      END IF;
    ELSIF k = 'ordem' THEN
      IF pg_catalog.jsonb_typeof(p->k) IS DISTINCT FROM 'number' THEN RAISE EXCEPTION USING ERRCODE='22023', MESSAGE='catalog_volume_invalid'; END IF;
      v_int:=(p->>k)::numeric;
      IF v_int <> pg_catalog.trunc(v_int) OR v_int < 0 OR v_int > 9999 THEN RAISE EXCEPTION USING ERRCODE='22023', MESSAGE='catalog_volume_invalid'; END IF;
      v_out:=v_out||pg_catalog.jsonb_build_object(k,v_int::int);
    ELSE RAISE EXCEPTION USING ERRCODE='22023', MESSAGE='catalog_volume_invalid';
    END IF;
  END LOOP;
  IF p_create AND NOT (v_out ? 'volume_ml' AND v_out ? 'preco_brl') THEN RAISE EXCEPTION USING ERRCODE='22023', MESSAGE='catalog_volume_invalid'; END IF;
  IF NOT p_create AND v_out = '{}'::jsonb THEN RAISE EXCEPTION USING ERRCODE='22023', MESSAGE='catalog_volume_invalid'; END IF;
  RETURN v_out;
END;
$function$

CREATE OR REPLACE FUNCTION platform_private.catalog_volume_pricing(p_parent jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 IMMUTABLE
 SET search_path TO ''
AS $function$
DECLARE l jsonb:=platform_private.catalog_volume_dec(p_parent->'valor_litro_brl');
  d jsonb:=platform_private.catalog_volume_dec(p_parent->'valor_dose_brl');
  h jsonb:=platform_private.catalog_volume_dec(p_parent->'valor_ha_brl');
BEGIN
  IF l IS NULL OR d IS NULL OR h IS NULL THEN RAISE EXCEPTION USING ERRCODE='40001', MESSAGE='catalog_volume_pricing_unexpected'; END IF;
  RETURN pg_catalog.jsonb_build_object('valor_litro_brl',l,'valor_dose_brl',d,'valor_ha_brl',h,'updated_at',p_parent->'updated_at');
END;
$function$

CREATE OR REPLACE FUNCTION platform_private.catalog_volume_settle(p_tipo text, p_item uuid, p_before jsonb, p_touches_active boolean, p_confirmed boolean, p_allow_reprice boolean, p_token text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE v_after jsonb; v_strip text[]:=ARRAY['valor_litro_brl','valor_dose_brl','valor_ha_brl','updated_at'];
  v_pb jsonb; v_pa jsonb; v_repriced boolean;
BEGIN
  v_after:=platform_private.catalog_volume_parent(p_tipo,p_item,false);
  IF (v_after - v_strip) IS DISTINCT FROM (p_before - v_strip) THEN
    RAISE EXCEPTION USING ERRCODE='40001', MESSAGE='catalog_volume_parent_protected_changed'; END IF;
  v_pb:=platform_private.catalog_volume_pricing(p_before); v_pa:=platform_private.catalog_volume_pricing(v_after);
  v_repriced:=(v_pb - 'updated_at') IS DISTINCT FROM (v_pa - 'updated_at');
  IF v_repriced AND NOT p_allow_reprice THEN
    RAISE EXCEPTION USING ERRCODE='40001', MESSAGE='catalog_volume_unexpected_repricing'; END IF;
  IF (p_touches_active OR v_repriced) AND NOT COALESCE(p_confirmed,false) THEN
    IF p_token IS NULL THEN RAISE EXCEPTION USING ERRCODE='40001', MESSAGE='catalog_volume_confirmation_failed'; END IF;
    RAISE EXCEPTION USING ERRCODE='55000', MESSAGE='catalog_volume_confirmation_required',
      DETAIL=pg_catalog.jsonb_build_object('token',p_token,'repriced',v_repriced,
        'parent_before',v_pb - 'updated_at','parent_after',v_pa - 'updated_at')::text;
  END IF;
  RETURN pg_catalog.jsonb_build_object('repriced',v_repriced,'parent_before',v_pb,'parent_after',v_pa);
END;
$function$

CREATE OR REPLACE FUNCTION platform_private.lab_partner_order_authorized(p_order_id uuid)
 RETURNS boolean
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE v_uid uuid:=auth.uid(); v_org uuid;
BEGIN
 IF v_uid IS NULL OR NOT (public.has_role(v_uid,'administrador') OR public.has_role(v_uid,'producao') OR public.has_role(v_uid,'gestor')) THEN RETURN false; END IF;
 v_org:=public.h15_actor_organization();
 IF v_org IS NULL THEN RETURN false; END IF;
 RETURN EXISTS(SELECT 1 FROM public.partner_orders o JOIN public.partner_accounts p ON p.id=o.partner_id
 WHERE o.id=p_order_id AND p.commercial_owner_organization_id=v_org AND p.ativo IS TRUE AND p.deleted_at IS NULL
 AND (p.client_id IS NULL OR EXISTS(SELECT 1 FROM public.clientes c WHERE c.id=p.client_id AND c.organization_id=v_org)));
END $function$

CREATE OR REPLACE FUNCTION platform_private.c1b_catalog_visibility_scope(p_partner uuid)
 RETURNS uuid[]
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE v_actor uuid; v_owner uuid;
BEGIN
 IF auth.uid() IS NULL THEN RAISE EXCEPTION 'auth_required' USING ERRCODE='42501'; END IF;
 v_actor := platform_private.h15_actor_organization();
 IF v_actor IS NULL AND NOT public.is_platform_superadmin(auth.uid()) THEN
  RAISE EXCEPTION 'catalog_actor_unavailable' USING ERRCODE='42501'; END IF;
 IF p_partner IS NULL THEN
  SELECT o.partner_account_id INTO p_partner FROM public.organizations o WHERE o.id=v_actor;
 END IF;
 IF p_partner IS NOT NULL THEN
  SELECT pa.commercial_owner_organization_id INTO v_owner FROM public.partner_accounts pa
   JOIN public.organizations o ON o.id=pa.commercial_owner_organization_id AND o.ativo IS TRUE AND o.status='ativa'
   WHERE pa.id=p_partner AND pa.ativo IS TRUE AND pa.deleted_at IS NULL;
  IF v_owner IS NULL THEN RAISE EXCEPTION 'catalog_commercial_owner_unavailable' USING ERRCODE='42501'; END IF;
 END IF;
 IF v_actor IS NULL AND v_owner IS NULL THEN RAISE EXCEPTION 'catalog_scope_unavailable' USING ERRCODE='42501'; END IF;
 RETURN array_remove(ARRAY[v_actor,v_owner],NULL);
END $function$

CREATE OR REPLACE FUNCTION platform_private.c2_internal_order_target_reason(_uid uuid, _partner uuid)
 RETURNS text
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE s record; org uuid;
BEGIN
  -- Mirrors LIVE guards; NULL means allowed. Never authorizes by itself: callers must RAISE.
  IF _uid IS NULL OR auth.uid() IS DISTINCT FROM _uid THEN RETURN 'auth_required'; END IF;
  IF NOT platform_private.b2b_internal_commercial_actor() THEN RETURN 'actor_not_allowed'; END IF;
  SELECT * INTO s FROM platform_private.b2b_actor_scope(_uid);
  IF s.profile_ok IS NOT TRUE THEN RETURN 'inactive_scope'; END IF;
  IF NOT public._saas_user_has_feature(_uid,'pedidos_b2b') THEN RETURN 'feature_disabled'; END IF;
  org := public.h15_actor_organization();
  IF org IS NULL THEN RETURN 'actor_not_allowed'; END IF;
  IF _partner IS NULL THEN RETURN NULL; END IF;
  IF NOT EXISTS (SELECT 1 FROM public.partner_accounts p
       WHERE p.id=_partner AND p.ativo IS TRUE AND p.deleted_at IS NULL AND p.commercial_owner_organization_id=org
         AND (p.client_id IS NULL OR EXISTS (SELECT 1 FROM public.clientes c WHERE c.id=p.client_id AND c.organization_id=org))) THEN
    RETURN 'target_outside_portfolio';
  END IF;
  RETURN NULL;
END $function$

CREATE OR REPLACE FUNCTION public.fiscal_json_has_sensitive_key(p jsonb)
 RETURNS boolean
 LANGUAGE plpgsql
 IMMUTABLE
 SET search_path TO 'public'
AS $function$
DECLARE
  k text;
  v jsonb;
  item jsonb;
  sensitive constant text[] := ARRAY[
    'token','password','senha','secret','api_key','apikey',
    'private_key','privatekey','pfx','p12',
    'certificate_content','certificate_pem','pem',
    'authorization','bearer'
  ];
BEGIN
  IF p IS NULL THEN RETURN false; END IF;
  IF jsonb_typeof(p) = 'object' THEN
    FOR k, v IN SELECT key, value FROM jsonb_each(p) LOOP
      IF lower(k) = ANY (sensitive) THEN
        RETURN true;
      END IF;
      IF public.fiscal_json_has_sensitive_key(v) THEN
        RETURN true;
      END IF;
    END LOOP;
    RETURN false;
  ELSIF jsonb_typeof(p) = 'array' THEN
    FOR item IN SELECT value FROM jsonb_array_elements(p) LOOP
      IF public.fiscal_json_has_sensitive_key(item) THEN
        RETURN true;
      END IF;
    END LOOP;
    RETURN false;
  END IF;
  RETURN false;
END;
$function$

CREATE OR REPLACE FUNCTION public._fiscal_rtc_assert_payload(payload jsonb, kind text)
 RETURNS void
 LANGUAGE plpgsql
 IMMUTABLE
 SET search_path TO 'pg_catalog', 'public'
AS $function$
DECLARE
  k text; sz int;
  company_keys text[] := ARRAY['schema_version','source_document','source_version',
    'effective_from','last_reviewed_at','rtc_environment','transition_year',
    'accounting_review_notes','accounting_review_status','additional_fields'];
  item_keys text[] := ARRAY['schema_version','source_document','source_version',
    'effective_from','last_reviewed_at','cst_ibs_cbs','c_class_trib',
    'c_credito_presumido','c_ind_op','aliquota_cbs','aliquota_ibs_uf',
    'aliquota_ibs_municipio','aliquota_cbs_reference','aliquota_ibs_reference',
    'reducao','diferimento','monofasia','accounting_notes',
    'accounting_review_status','additional_fields'];
  allowed text[];
BEGIN
  IF payload IS NULL OR jsonb_typeof(payload) <> 'object' THEN
    RAISE EXCEPTION 'FISCAL_RTC_INVALID_PAYLOAD' USING ERRCODE='22023'; END IF;
  IF public.fiscal_rtc_has_sensitive_key(payload) THEN
    RAISE EXCEPTION 'FISCAL_RTC_SENSITIVE_KEY' USING ERRCODE='22023'; END IF;
  sz := length(payload::text);
  IF sz > 65536 THEN
    RAISE EXCEPTION 'FISCAL_RTC_PAYLOAD_TOO_LARGE' USING ERRCODE='22023'; END IF;
  IF NOT (payload ? 'schema_version') OR (payload->>'schema_version') NOT IN ('1') THEN
    RAISE EXCEPTION 'FISCAL_RTC_SCHEMA_VERSION_UNSUPPORTED' USING ERRCODE='22023'; END IF;
  allowed := CASE WHEN kind='company' THEN company_keys ELSE item_keys END;
  FOR k IN SELECT jsonb_object_keys(payload) LOOP
    IF NOT (k = ANY(allowed)) THEN
      RAISE EXCEPTION 'FISCAL_RTC_UNKNOWN_FIELD' USING ERRCODE='22023'; END IF;
  END LOOP;
  IF payload ? 'additional_fields'
     AND jsonb_typeof(payload->'additional_fields') <> 'object' THEN
    RAISE EXCEPTION 'FISCAL_RTC_INVALID_ADDITIONAL_FIELDS' USING ERRCODE='22023'; END IF;
  IF kind='company' AND payload ? 'rtc_environment'
     AND (payload->>'rtc_environment') NOT IN ('NOT_CONFIGURED','HOMOLOGATION') THEN
    RAISE EXCEPTION 'FISCAL_RTC_INVALID_ENVIRONMENT' USING ERRCODE='22023'; END IF;
  IF payload ? 'accounting_review_status'
     AND (payload->>'accounting_review_status') NOT IN ('PENDING','REVIEWED') THEN
    RAISE EXCEPTION 'FISCAL_RTC_INVALID_REVIEW_STATUS' USING ERRCODE='22023'; END IF;
  FOR k IN SELECT unnest(ARRAY['aliquota_cbs','aliquota_ibs_uf',
    'aliquota_ibs_municipio','aliquota_cbs_reference','aliquota_ibs_reference']) LOOP
    IF payload ? k THEN
      IF jsonb_typeof(payload->k) <> 'number'
         OR (payload->>k)::numeric < 0 OR (payload->>k)::numeric > 100 THEN
        RAISE EXCEPTION 'FISCAL_RTC_INVALID_PERCENT' USING ERRCODE='22023'; END IF;
    END IF;
  END LOOP;
  FOR k IN SELECT unnest(ARRAY['cst_ibs_cbs','c_class_trib',
    'c_credito_presumido','c_ind_op']) LOOP
    IF payload ? k THEN
      IF jsonb_typeof(payload->k) <> 'string'
         OR length(payload->>k) < 1 OR length(payload->>k) > 12
         OR (payload->>k) !~ '^[A-Za-z0-9._-]+$' THEN
        RAISE EXCEPTION 'FISCAL_RTC_INVALID_CODE' USING ERRCODE='22023'; END IF;
    END IF;
  END LOOP;
  FOR k IN SELECT unnest(ARRAY['effective_from','last_reviewed_at']) LOOP
    IF payload ? k THEN
      IF jsonb_typeof(payload->k) <> 'string'
         OR (payload->>k) !~ '^\d{4}-\d{2}-\d{2}(T.*)?$' THEN
        RAISE EXCEPTION 'FISCAL_RTC_INVALID_DATE' USING ERRCODE='22023'; END IF;
    END IF;
  END LOOP;
  IF payload ? 'source_document' AND length(payload->>'source_document') > 120 THEN
    RAISE EXCEPTION 'FISCAL_RTC_STRING_TOO_LONG' USING ERRCODE='22023'; END IF;
  IF payload ? 'source_version' AND length(payload->>'source_version') > 60 THEN
    RAISE EXCEPTION 'FISCAL_RTC_STRING_TOO_LONG' USING ERRCODE='22023'; END IF;
  IF payload ? 'accounting_review_notes'
     AND length(payload->>'accounting_review_notes') > 4000 THEN
    RAISE EXCEPTION 'FISCAL_RTC_STRING_TOO_LONG' USING ERRCODE='22023'; END IF;
  IF payload ? 'accounting_notes'
     AND length(payload->>'accounting_notes') > 2000 THEN
    RAISE EXCEPTION 'FISCAL_RTC_STRING_TOO_LONG' USING ERRCODE='22023'; END IF;
  -- ------------------------------------------------------------------
  -- Fase 3.19.5 - validacao NFS-e Nacional dentro de additional_fields.
  -- Codigos estaveis; fail-fast; sem catch silenciador.
  -- ------------------------------------------------------------------
  IF payload ? 'additional_fields' THEN
    DECLARE af jsonb := payload->'additional_fields';
    BEGIN
      IF af ? 'finNFSe' THEN
        IF jsonb_typeof(af->'finNFSe') <> 'string' THEN
          RAISE EXCEPTION 'FISCAL_RTC_NFSE_INVALID_CODE:finNFSe' USING ERRCODE='22023'; END IF;
        IF length(btrim(af->>'finNFSe')) < 1 OR length(btrim(af->>'finNFSe')) > 30 THEN
          RAISE EXCEPTION 'FISCAL_RTC_NFSE_INVALID_CODE:finNFSe' USING ERRCODE='22023'; END IF;
      END IF;
      IF af ? 'tpNFSeDebito' THEN
        IF jsonb_typeof(af->'tpNFSeDebito') <> 'string' THEN
          RAISE EXCEPTION 'FISCAL_RTC_NFSE_INVALID_CODE:tpNFSeDebito' USING ERRCODE='22023'; END IF;
        IF length(btrim(af->>'tpNFSeDebito')) < 1 OR length(btrim(af->>'tpNFSeDebito')) > 30 THEN
          RAISE EXCEPTION 'FISCAL_RTC_NFSE_INVALID_CODE:tpNFSeDebito' USING ERRCODE='22023'; END IF;
      END IF;
      IF af ? 'tpNFSeCredito' THEN
        IF jsonb_typeof(af->'tpNFSeCredito') <> 'string' THEN
          RAISE EXCEPTION 'FISCAL_RTC_NFSE_INVALID_CODE:tpNFSeCredito' USING ERRCODE='22023'; END IF;
        IF length(btrim(af->>'tpNFSeCredito')) < 1 OR length(btrim(af->>'tpNFSeCredito')) > 30 THEN
          RAISE EXCEPTION 'FISCAL_RTC_NFSE_INVALID_CODE:tpNFSeCredito' USING ERRCODE='22023'; END IF;
      END IF;
      IF af ? 'gIBSCBSAjuste' THEN
        IF jsonb_typeof(af->'gIBSCBSAjuste') <> 'boolean' THEN
          RAISE EXCEPTION 'FISCAL_RTC_NFSE_INVALID_TOGGLE:gIBSCBSAjuste' USING ERRCODE='22023'; END IF;
      END IF;
      IF af ? 'vAjusteBC' THEN
        IF jsonb_typeof(af->'vAjusteBC') <> 'number' THEN
          RAISE EXCEPTION 'FISCAL_RTC_NFSE_INVALID_VALUE:vAjusteBC' USING ERRCODE='22023'; END IF;
        IF (af->>'vAjusteBC')::numeric < 0 THEN
          RAISE EXCEPTION 'FISCAL_RTC_NFSE_INVALID_VALUE:vAjusteBC' USING ERRCODE='22023'; END IF;
        IF NOT (af ? 'gIBSCBSAjuste') THEN
          RAISE EXCEPTION 'FISCAL_RTC_NFSE_VALUE_WITHOUT_TOGGLE:vAjusteBC' USING ERRCODE='22023'; END IF;
        IF jsonb_typeof(af->'gIBSCBSAjuste') <> 'boolean'
           OR (af->>'gIBSCBSAjuste')::boolean IS DISTINCT FROM true THEN
          RAISE EXCEPTION 'FISCAL_RTC_NFSE_VALUE_WITHOUT_TOGGLE:vAjusteBC' USING ERRCODE='22023'; END IF;
      END IF;
    END;
  END IF;
END; $function$

CREATE OR REPLACE FUNCTION public.fiscal_validate_snapshot_keys(p_obj jsonb, p_allowed text[], p_label text)
 RETURNS void
 LANGUAGE plpgsql
 IMMUTABLE
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE k text;
BEGIN
  IF p_obj IS NULL OR jsonb_typeof(p_obj) <> 'object' THEN
    RETURN;
  END IF;
  FOR k IN SELECT jsonb_object_keys(p_obj) LOOP
    IF NOT (k = ANY(p_allowed)) THEN
      RAISE EXCEPTION 'snapshot_unknown_key:%:%', p_label, k
        USING ERRCODE = '22023';
    END IF;
  END LOOP;
END;
$function$

CREATE OR REPLACE FUNCTION public.fn_fiscal_apply_tax_v2(r fiscal_tax_rules, _ctx jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 IMMUTABLE
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE
  base_raw numeric; base_eff numeric; val numeric := 0;
  extra jsonb := '{}'::jsonb;
  icms_own numeric; base_st numeric; v_st numeric;
  v_mode text; v_src text; v_red numeric; v_manual numeric;
  v_manual_by text; v_manual_at text; v_manual_reason text;
  r_int numeric; r_inter numeric; share numeric;
  v_difal_dest numeric; v_difal_orig numeric; v_fcp numeric;
BEGIN
  IF r.tax_kind IN ('IBS','CBS','IS') THEN
    RAISE EXCEPTION 'FISCAL_RTC_ENGINE_UNAVAILABLE: IBS/CBS/IS permanecem em scaffolding bloqueado ate regra e leiaute oficiais.'
      USING HINT = 'Nao simule tributos da reforma como se fossem vigentes.';
  END IF;

  base_raw := public.fn_fiscal_item_base(r.base_components, _ctx);
  IF base_raw < 0 THEN
    RAISE EXCEPTION 'FISCAL_TAX_BASE_NEGATIVE: base negativa para tributo %.', r.tax_kind;
  END IF;
  -- Resolucao canonica do percentual de reducao da base (NONE / FIXED / MANUAL).
  v_mode := coalesce(r.base_reduction_mode,'NONE');
  v_manual := nullif(btrim(coalesce(_ctx->>'manualBaseReductionPct','')),'')::numeric;
  v_manual_by := nullif(btrim(coalesce(_ctx->>'manualBy','')),'');
  v_manual_at := nullif(btrim(coalesce(_ctx->>'manualAt','')),'');
  v_manual_reason := nullif(btrim(coalesce(_ctx->>'manualReason','')),'');

  IF v_mode = 'MANUAL' THEN
    IF v_manual IS NULL THEN
      RAISE EXCEPTION 'FISCAL_BASE_REDUCTION_INPUT_REQUIRED: tributo % exige percentual de reducao informado na preparacao.', r.tax_kind;
    END IF;
    IF v_manual < 0 OR v_manual > 100 THEN
      RAISE EXCEPTION 'FISCAL_BASE_REDUCTION_OUT_OF_RANGE: percentual de reducao % invalido para %; use 0 a 100.', v_manual, r.tax_kind;
    END IF;
    IF v_manual_reason IS NULL THEN
      RAISE EXCEPTION 'FISCAL_BASE_REDUCTION_REASON_REQUIRED: informe o motivo da reducao manual da base de calculo (%).', r.tax_kind;
    END IF;
    v_red := v_manual;
    v_src := 'MANUAL';
  ELSIF v_mode = 'FIXED' THEN
    IF v_manual IS NOT NULL THEN
      RAISE EXCEPTION 'FISCAL_BASE_REDUCTION_NOT_EDITABLE: regra % define reducao fixa; percentual manual nao e aceito.', r.rule_key;
    END IF;
    v_red := coalesce(r.base_reduction_pct,0);
    v_src := 'FIXED';
  ELSE
    IF v_manual IS NOT NULL THEN
      RAISE EXCEPTION 'FISCAL_BASE_REDUCTION_NOT_ALLOWED: regra % nao admite reducao da base de calculo.', r.rule_key;
    END IF;
    v_red := 0;
    v_src := 'NONE';
  END IF;

  base_eff := public.fn_fiscal_round(base_raw * (1 - v_red/100));

  IF r.calc_mode IN ('EXEMPT_DOCUMENTED','NOT_TAXED_DOCUMENTED','SUSPENDED_DOCUMENTED') THEN
    -- Modo documentado: preserva base/CST/motivo; nao apaga informacao exigida no leiaute.
    IF nullif(btrim(coalesce(r.justification,'')),'') IS NULL
       OR nullif(btrim(coalesce(r.legal_basis,'')),'') IS NULL THEN
      RAISE EXCEPTION 'FISCAL_TAX_RULE_INCOMPLETE: modo % exige motivo e base legal documentados.', r.calc_mode;
    END IF;
    val := 0;
    extra := extra || jsonb_build_object('documentedMode', r.calc_mode, 'taxedBase', base_eff);

  ELSIF r.calc_mode = 'DEFERRED_DOCUMENTED' THEN
    -- Diferimento: exige percentual, motivo e base legal; valor diferido explicitado.
    IF nullif(btrim(coalesce(r.justification,'')),'') IS NULL
       OR nullif(btrim(coalesce(r.legal_basis,'')),'') IS NULL THEN
      RAISE EXCEPTION 'FISCAL_TAX_RULE_INCOMPLETE: diferimento exige motivo e base legal documentados.';
    END IF;
    IF r.rate IS NULL OR r.deferral_pct IS NULL THEN
      RAISE EXCEPTION 'FISCAL_TAX_RULE_INCOMPLETE: diferimento exige aliquota e deferral_pct.';
    END IF;
    val := public.fn_fiscal_round(base_eff * r.rate / 100);
    extra := extra || jsonb_build_object('documentedMode', r.calc_mode,
      'deferralPct', r.deferral_pct,
      'deferredValue', public.fn_fiscal_round(val * r.deferral_pct / 100));
    val := public.fn_fiscal_round(val * (1 - r.deferral_pct/100));

  ELSIF r.calc_mode <> 'PERCENT' THEN
    RAISE EXCEPTION 'FISCAL_TAX_RULE_INCOMPLETE: calc_mode % nao suportado pelo motor F3.', r.calc_mode;

  ELSIF r.tax_kind IN ('ICMS','PIS','COFINS','IPI','ISS') THEN
    IF r.rate IS NULL THEN
      RAISE EXCEPTION 'FISCAL_TAX_RULE_INCOMPLETE: aliquota ausente para tributo %.', r.tax_kind;
    END IF;
    val := public.fn_fiscal_round(base_eff * r.rate / 100);
    IF coalesce(r.deferral_pct,0) > 0 THEN
      extra := extra || jsonb_build_object('deferredValue',
        public.fn_fiscal_round(val * r.deferral_pct / 100));
      val := public.fn_fiscal_round(val * (1 - r.deferral_pct/100));
    END IF;

  ELSIF r.tax_kind = 'ICMS_ST' THEN
    IF coalesce(r.st_modality,'MVA') <> 'MVA' THEN
      RAISE EXCEPTION 'FISCAL_TAX_RULE_INCOMPLETE: modalidade de BC ST % nao implementada nesta fase.', r.st_modality;
    END IF;
    IF r.mva_pct IS NULL OR r.internal_rate_pct IS NULL THEN
      RAISE EXCEPTION 'FISCAL_TAX_RULE_INCOMPLETE: ICMS-ST exige mva_pct e internal_rate_pct.';
    END IF;
    icms_own := coalesce((_ctx->>'icmsOwnValue')::numeric, 0);
    base_st := public.fn_fiscal_round(base_eff * (1 + r.mva_pct/100));
    v_st := public.fn_fiscal_round(base_st * r.internal_rate_pct / 100);
    IF coalesce(r.credit_own_icms,true) THEN
      v_st := public.fn_fiscal_round(v_st - icms_own);
    END IF;
    IF v_st < 0 THEN v_st := 0; END IF;
    val := v_st;
    extra := extra || jsonb_build_object('modBCST', r.st_modality, 'baseST', base_st,
      'internalRatePct', r.internal_rate_pct, 'mvaPct', r.mva_pct,
      'creditedOwnIcms', coalesce(r.credit_own_icms,true), 'ownIcmsValue', icms_own);

  ELSIF r.tax_kind IN ('FCP','FCP_ST') THEN
    IF r.fcp_rate IS NULL AND r.fcp_st_rate IS NULL THEN
      RAISE EXCEPTION 'FISCAL_TAX_RULE_INCOMPLETE: FCP exige aliquota propria (fcp_rate/fcp_st_rate).';
    END IF;
    IF r.tax_kind = 'FCP' THEN
      IF r.fcp_rate IS NULL THEN
        RAISE EXCEPTION 'FISCAL_TAX_RULE_INCOMPLETE: FCP exige fcp_rate.';
      END IF;
      val := public.fn_fiscal_round(base_eff * r.fcp_rate / 100);
      extra := extra || jsonb_build_object('fcpBase', base_eff, 'fcpRate', r.fcp_rate);
    ELSE
      IF r.fcp_st_rate IS NULL THEN
        RAISE EXCEPTION 'FISCAL_TAX_RULE_INCOMPLETE: FCP-ST exige fcp_st_rate.';
      END IF;
      base_st := coalesce((_ctx->>'baseST')::numeric, null);
      IF base_st IS NULL THEN
        RAISE EXCEPTION 'FISCAL_TAX_RULE_INCOMPLETE: FCP-ST exige base de ST previamente apurada.';
      END IF;
      val := public.fn_fiscal_round(base_st * r.fcp_st_rate / 100);
      extra := extra || jsonb_build_object('fcpStBase', base_st, 'fcpStRate', r.fcp_st_rate);
    END IF;

  ELSIF r.tax_kind = 'DIFAL' THEN
    r_int := r.internal_rate_pct; r_inter := r.interstate_rate_pct;
    share := r.difal_dest_share_pct;
    IF r_int IS NULL OR r_inter IS NULL OR share IS NULL THEN
      RAISE EXCEPTION 'FISCAL_TAX_RULE_INCOMPLETE: DIFAL exige internal_rate_pct, interstate_rate_pct e difal_dest_share_pct.';
    END IF;
    IF r_int < r_inter THEN
      RAISE EXCEPTION 'FISCAL_TAX_RULE_INCOMPLETE: aliquota interna do destino menor que a interestadual; parametros incoerentes.';
    END IF;
    val := public.fn_fiscal_round(base_eff * (r_int - r_inter) / 100);
    v_difal_dest := public.fn_fiscal_round(val * share / 100);
    v_difal_orig := public.fn_fiscal_round(val - v_difal_dest);
    v_fcp := CASE WHEN r.fcp_rate IS NULL THEN NULL
                  ELSE public.fn_fiscal_round(base_eff * r.fcp_rate / 100) END;
    extra := extra || jsonb_build_object(
      'internalRatePct', r_int, 'interstateRatePct', r_inter,
      'destSharePct', share, 'valueDestination', v_difal_dest,
      'valueOrigin', v_difal_orig, 'fcpValue', v_fcp);

  ELSE
    RAISE EXCEPTION 'FISCAL_TAX_KIND_UNSUPPORTED: tributo % sem formula canonica implementada.', r.tax_kind;
  END IF;

  RETURN jsonb_build_object(
    'taxKind', r.tax_kind, 'calcMode', r.calc_mode, 'formula', 'F3.4/'||r.tax_kind,
    'ruleId', r.id, 'ruleKey', r.rule_key, 'ruleVersion', r.version,
    'sourceId', r.source_id, 'legalBasis', r.legal_basis, 'legalVersion', r.legal_version,
    'justification', r.justification,
    'cst', r.cst, 'csosn', r.csosn, 'crt', r.crt,
    'rate', r.rate, 'baseReductionPct', v_red, 'deferralPct', r.deferral_pct,
    'baseReductionMode', v_mode, 'baseReductionSource', v_src,
    'baseReductionRulePct', r.base_reduction_pct,
    'baseReductionAppliedBy', CASE WHEN v_src = 'MANUAL' THEN v_manual_by ELSE NULL END,
    'baseReductionAppliedAt', CASE WHEN v_src = 'MANUAL' THEN v_manual_at ELSE NULL END,
    'baseReductionReason', CASE WHEN v_src = 'MANUAL' THEN v_manual_reason ELSE NULL END,
    'baseComponents', r.base_components,
    'baseOriginal', base_raw, 'base', base_eff, 'value', val,
    'params', extra);
END $function$

CREATE OR REPLACE FUNCTION public.fn_fiscal_rule_validate_synthetic(_tax_kind text, _rule fiscal_tax_rules, _ctx jsonb)
 RETURNS text
 LANGUAGE plpgsql
 IMMUTABLE
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE msg text;
BEGIN
  PERFORM public.fn_fiscal_apply_tax_v2(_rule, _ctx);
  RETURN 'OK';
EXCEPTION WHEN OTHERS THEN
  msg := coalesce(SQLERRM,'');
  IF msg LIKE '%ENGINE_UNAVAILABLE%' THEN RETURN 'ENGINE_UNAVAILABLE'; END IF;
  IF msg LIKE '%AMBIGUOUS%'          THEN RETURN 'AMBIGUOUS'; END IF;
  IF msg LIKE '%NOT_FOUND%'          THEN RETURN 'NOT_FOUND'; END IF;
  RETURN 'INCOMPLETE';
END $function$

CREATE OR REPLACE FUNCTION public.validate_catalog_approval_checklist(p_kind text, p_checklist jsonb, p_b2b_enabled boolean, p_has_sources boolean, p_aprovado_sem_fonte boolean)
 RETURNS void
 LANGUAGE plpgsql
 IMMUTABLE
 SET search_path TO 'public'
AS $function$
DECLARE
  v_required text[];
  v_key text;
BEGIN
  IF p_kind NOT IN ('micro','produto') THEN
    RAISE EXCEPTION 'approval_invalid_kind';
  END IF;

  IF p_checklist IS NULL OR jsonb_typeof(p_checklist) <> 'object' THEN
    RAISE EXCEPTION 'approval_checklist_empty';
  END IF;

  IF (SELECT count(*) FROM jsonb_object_keys(p_checklist)) = 0 THEN
    RAISE EXCEPTION 'approval_checklist_empty';
  END IF;

  IF p_kind = 'micro' THEN
    v_required := ARRAY['resumo','mecanismo','beneficios','tecnica','produtor','alvos','cuidados','regulatorias'];
  ELSE
    v_required := ARRAY['resumo','composicao','beneficio','tecnica','produtor','alvos','cuidados'];
  END IF;

  FOREACH v_key IN ARRAY v_required LOOP
    IF NOT COALESCE((p_checklist ->> v_key)::boolean, false) THEN
      RAISE EXCEPTION 'approval_checklist_missing_%', v_key;
    END IF;
  END LOOP;

  IF p_b2b_enabled AND NOT COALESCE((p_checklist ->> 'b2b')::boolean, false) THEN
    RAISE EXCEPTION 'approval_checklist_missing_b2b';
  END IF;

  IF p_has_sources THEN
    IF NOT COALESCE((p_checklist ->> 'fontes')::boolean, false) THEN
      RAISE EXCEPTION 'approval_checklist_missing_fontes';
    END IF;
  ELSE
    IF NOT p_aprovado_sem_fonte THEN
      RAISE EXCEPTION 'approval_missing_fontes';
    END IF;
    IF NOT COALESCE((p_checklist ->> 'sem_fonte')::boolean, false) THEN
      RAISE EXCEPTION 'approval_checklist_missing_sem_fonte';
    END IF;
  END IF;
END;
$function$

CREATE OR REPLACE FUNCTION public.send_partner_simulation_to_manager_secure(p_simulation_id uuid)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_uid uuid := auth.uid();
  v_sim partner_simulations%ROWTYPE;
  v_partner_id uuid;
  v_allowed boolean := false;
BEGIN

  IF NOT public.b2b_phase1_simulation_visible(p_simulation_id) THEN RAISE EXCEPTION 'b2b_phase1_scope_denied' USING ERRCODE='42501'; END IF;
  IF v_uid IS NULL THEN RAISE EXCEPTION 'Não autenticado'; END IF;
  SELECT * INTO v_sim FROM partner_simulations WHERE id = p_simulation_id;
  IF NOT FOUND THEN RAISE EXCEPTION 'Simulação não encontrada'; END IF;
  IF v_sim.status <> 'rascunho' THEN RAISE EXCEPTION 'Somente simulações em rascunho podem ser enviadas'; END IF;

  v_partner_id := get_user_partner_id();

  IF has_role(v_uid, 'administrador') OR has_role(v_uid, 'gestor_comercial') THEN v_allowed := true;
  ELSIF has_role(v_uid, 'parceiro_b2b_tecnico') AND v_sim.created_by = v_uid THEN v_allowed := true;
  ELSIF has_role(v_uid, 'parceiro_b2b') AND (v_sim.created_by = v_uid OR v_sim.partner_id = v_partner_id) THEN v_allowed := true;
  END IF;
  IF NOT v_allowed THEN RAISE EXCEPTION 'Sem permissão para enviar esta simulação'; END IF;

  UPDATE partner_simulations SET status = 'enviada_gestor', updated_at = now() WHERE id = p_simulation_id;

  INSERT INTO partner_audit_logs (partner_id, usuario_id, acao, dados_anteriores, dados_novos)
  VALUES (v_sim.partner_id, v_uid, 'simulation_sent_to_manager',
    jsonb_build_object('simulation_id', p_simulation_id, 'status', v_sim.status),
    jsonb_build_object('simulation_id', p_simulation_id, 'status', 'enviada_gestor'));

  PERFORM public.insert_partner_catalog_access_log_internal(
    'simulation_sent_to_manager', v_sim.partner_id, v_uid,
    v_sim.cliente_id, p_simulation_id, NULL, NULL, '{}'::jsonb);
END;
$function$

CREATE OR REPLACE FUNCTION public.fn_fiscal_tax_input_valid(_input jsonb)
 RETURNS boolean
 LANGUAGE plpgsql
 IMMUTABLE
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE
  k text; v jsonb; ik text; pct numeric;
  allowed_kinds text[] := ARRAY['ICMS','ICMS_ST','FCP','FCP_ST','DIFAL','PIS','COFINS','IPI'];
BEGIN
  IF _input IS NULL THEN RETURN true; END IF;
  IF jsonb_typeof(_input) <> 'object' THEN RETURN false; END IF;

  FOR k, v IN SELECT * FROM jsonb_each(_input) LOOP
    IF NOT (k = ANY(allowed_kinds)) THEN RETURN false; END IF;
    IF jsonb_typeof(v) <> 'object' THEN RETURN false; END IF;
    FOR ik IN SELECT jsonb_object_keys(v) LOOP
      IF ik NOT IN ('baseReductionPct','baseReductionReason') THEN RETURN false; END IF;
    END LOOP;
    IF NOT (v ? 'baseReductionPct') THEN RETURN false; END IF;
    IF jsonb_typeof(v->'baseReductionPct') <> 'number' THEN RETURN false; END IF;
    pct := (v->>'baseReductionPct')::numeric;
    IF pct < 0 OR pct > 100 THEN RETURN false; END IF;
    IF v ? 'baseReductionReason' THEN
      IF jsonb_typeof(v->'baseReductionReason') <> 'string' THEN RETURN false; END IF;
      IF length(v->>'baseReductionReason') > 240 THEN RETURN false; END IF;
    END IF;
  END LOOP;

  RETURN true;
END $function$

CREATE OR REPLACE FUNCTION public.fn_fiscal_apportion_v1(p_total numeric, p_weights numeric[])
 RETURNS numeric[]
 LANGUAGE plpgsql
 IMMUTABLE
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE
  n int := coalesce(array_length(p_weights,1),0);
  total_c bigint;
  sum_w numeric := 0;
  out_c bigint[] := '{}';
  frac numeric[] := '{}';
  i int; assigned bigint := 0; rest bigint; idx int; best int; best_frac numeric;
  used boolean[] := '{}';
  res numeric[] := '{}';
BEGIN
  IF n = 0 THEN RETURN '{}'::numeric[]; END IF;
  IF coalesce(p_total,0) < 0 THEN
    RAISE EXCEPTION 'FISCAL_APPORTION_NEGATIVE_TOTAL' USING ERRCODE = '22023';
  END IF;
  total_c := round(coalesce(p_total,0) * 100)::bigint;
  FOR i IN 1..n LOOP
    IF coalesce(p_weights[i],0) < 0 THEN
      RAISE EXCEPTION 'FISCAL_APPORTION_NEGATIVE_WEIGHT' USING ERRCODE = '22023';
    END IF;
    sum_w := sum_w + coalesce(p_weights[i],0);
  END LOOP;

  IF total_c = 0 THEN
    FOR i IN 1..n LOOP res := res || 0::numeric; END LOOP;
    RETURN res;
  END IF;

  FOR i IN 1..n LOOP
    IF sum_w > 0 THEN
      out_c := out_c || floor(total_c * coalesce(p_weights[i],0) / sum_w)::bigint;
      frac  := frac  || ((total_c * coalesce(p_weights[i],0) / sum_w) - floor(total_c * coalesce(p_weights[i],0) / sum_w));
    ELSE
      out_c := out_c || floor(total_c / n)::bigint;
      frac  := frac  || ((total_c::numeric / n) - floor(total_c::numeric / n));
    END IF;
    used := used || false;
    assigned := assigned + out_c[i];
  END LOOP;

  rest := total_c - assigned;
  WHILE rest > 0 LOOP
    best := NULL; best_frac := -1;
    FOR i IN 1..n LOOP
      IF NOT used[i] AND frac[i] > best_frac THEN best := i; best_frac := frac[i]; END IF;
    END LOOP;
    IF best IS NULL THEN
      FOR i IN 1..n LOOP used[i] := false; END LOOP;
      CONTINUE;
    END IF;
    out_c[best] := out_c[best] + 1;
    used[best] := true;
    rest := rest - 1;
  END LOOP;

  FOR i IN 1..n LOOP res := res || (out_c[i]::numeric / 100); END LOOP;
  RETURN res;
END $function$

CREATE OR REPLACE FUNCTION public.h15_active_company()
 RETURNS uuid
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
DECLARE r uuid; n integer;
BEGIN
 PERFORM public.h15_require_staff();
 SELECT count(*),min(id::text)::uuid INTO n,r FROM public.company_fiscal_settings WHERE organization_id=public.h15_actor_organization() AND is_active;
 IF n<>1 THEN RAISE EXCEPTION 'H15_ACTIVE_COMPANY_AMBIGUOUS' USING ERRCODE='42501'; END IF;
